/// Middleware for automatically recording tool call activity
pub async fn activity_recording_middleware<B>(
    State(state): State<ContextServerState>,
    request: axum::extract::Request<B>,
    next: axum::middleware::Next<B>,
) -> axum::response::Response {
    // Extract session ID from headers if present
    let session_id = request
        .headers()
        .get("X-Session-ID")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("anonymous")
        .to_string();

    // Record the request
    let _ = state
        .activity_tx
        .send(ActivityEvent {
            session_id: session_id.clone(),
            activity_type: ActivityType::ToolCall,
            content: format!("{} {}", request.method(), request.uri().path()),
            metadata: serde_json::json!({
                "path": request.uri().path(),
                "method": request.method().as_str()
            }),
        })
        .await;

    // Continue with request
    let response = next.run(request).await;

    // Record response status
    let _ = state
        .activity_tx
        .send(ActivityEvent {
            session_id,
            activity_type: if response.status().is_success() {
                ActivityType::ToolCall
            } else {
                ActivityType::Error
            },
            content: format!("Response: {}", response.status()),
            metadata: serde_json::json!({ "status": response.status().as_u16() }),
        })
        .await;

    response
}

