#[async_trait]
impl StatePlugin for FreeDesktopPlugin {
    fn name(&self) -> &str {
        "freedesktop"
    }

    fn category(&self) -> &str {
        "system"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn is_available(&self) -> bool {
        true
    }

    fn unavailable_reason(&self) -> String {
        String::new()
    }

    fn dependencies(&self) -> Vec<String> {
        vec![]
    }

    fn schema(&self) -> Option<&PluginSchema> {
        self.schema.as_ref()
    }

    async fn validate(&self, state: &Value) -> op_state::ValidationResult {
        // Validate that the state conforms to FreeDesktop standards
        let validator = SchemaValidator::new();

        // Check for required fields
        let required_fields = ["name", "version", "plugin_type"];
        for field in &required_fields {
            if state.get(field).is_none() {
                return op_state::ValidationResult::Invalid {
                    errors: vec![format!("Missing required field: {}", field)],
                };
            }
        }

        // Validate plugin name is "freedesktop"
        if let Some(name) = state.get("name").and_then(|v| v.as_str()) {
            if name != "freedesktop" {
                return op_state::ValidationResult::Invalid {
                    errors: vec!["Plugin name must be 'freedesktop'".to_string()],
                };
            }
        }

        op_state::ValidationResult::Valid
    }

    async fn apply(&self, _changes: Vec<op_state::StateChange>) -> anyhow::Result<()> {
        // FreeDesktop plugin is primarily informational/structural
        // No actual system changes are made
        Ok(())
    }

    async fn query_current_state(&self) -> anyhow::Result<Value> {
        // Return the current state of FreeDesktop interfaces
        let interfaces: Vec<Value> = self
            .dbus_interfaces
            .values()
            .map(|iface| {
                simd_json::json!({
                    "name": iface.name.clone(),
                    "description": iface.description.clone(),
                    "methods_count": iface.methods.len(),
                    "signals_count": iface.signals.len(),
                    "properties_count": iface.properties.len(),
                })
            })
            .collect();

        let state = simd_json::json!({
            "name": "freedesktop",
            "version": "1.0.0",
            "plugin_type": "system",
