            "schema_renderer" => Arc::new(SchemaRendererPlugin::new()),
            "full_system" => Arc::new(FullSystemPlugin::new()),
            "login1" => Arc::new(Login1Plugin::new()),
            "dnsresolver" => Arc::new(DnsResolverPlugin::new()),
            "keyring" => Arc::new(KeyringPlugin::new()),
