fn parse_constraints(obj: &simd_json::BorrowedValue) -> Result<Vec<Constraint>> {
    use simd_json::prelude::*;

    let mut constraints = Vec::new();

    // Minimum constraint
    if let Some(min) = obj.get("minimum").and_then(|v| v.as_f64()) {
        constraints.push(Constraint::Min { value: min });
    }

    // Maximum constraint
    if let Some(max) = obj.get("maximum").and_then(|v| v.as_f64()) {
        constraints.push(Constraint::Max { value: max });
    }

    // MinLength constraint (for strings)
    if let Some(min_len) = obj.get("minLength").and_then(|v| v.as_i64()) {
        constraints.push(Constraint::MinLength { value: min_len as usize });
    }

    // MaxLength constraint (for strings)
    if let Some(max_len) = obj.get("maxLength").and_then(|v| v.as_i64()) {
        constraints.push(Constraint::MaxLength { value: max_len as usize });
    }

    // Pattern constraint (regex)
    if let Some(pattern) = obj.get("pattern").and_then(|v| v.as_str()) {
        constraints.push(Constraint::Pattern { regex: pattern.to_string() });
    }

    Ok(constraints)
}

